 c=s['candidate'][k];o=s['oracle'][k];r=s['candidate_over_oracle'][k];text+=f"| {label} | {c['median']/scale:.3f} | {o['median']/scale:.3f} | {r['median']:.6f} | {r['mad']:.6f} |\n"
