 c=x['candidate'];o=x['oracle'];text+=f"| {i} | {x['order']} | {c['prefill_ms']/1000:.3f} | {o['prefill_ms']/1000:.3f} | {c['gen_steady_tps']:.3f} | {o['gen_steady_tps']:.3f} | {c['process_peak_bytes']/gib:.3f} | {o['process_peak_bytes']/gib:.3f} |\n"
